import React, { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { useAuth } from '../auth/AuthContext';

export default function Login() {
  const { login } = useAuth();
  const navigate = useNavigate();
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');

  const handleLogin = (e) => {
    e.preventDefault();
    // จำลองการตรวจสอบ ถ้าพิมพ์ admin จะให้เป็นสิทธิ์ admin นอกนั้นเป็น member
    if (username.toLowerCase().includes('admin')) {
      login('admin');
      navigate('/admin');
    } else {
      login('member');
      navigate('/');
    }
  };

  return (
    <div style={{
      display: 'flex',
      justifyContent: 'center',
      alignItems: 'center',
      minHeight: '80vh',
      padding: '20px'
    }}>
      <div style={{
        width: '100%',
        maxWidth: '400px',
        background: '#FFFFFF',
        padding: '40px',
        borderRadius: '16px',
        boxShadow: '0 4px 20px rgba(0,0,0,0.05)',
        border: '1px solid #E2E8F0'
      }}>
        <h2 style={{ color: '#1E293B', marginTop: 0, marginBottom: '8px', fontSize: '24px' }}>ยินดีต้อนรับกลับ 👋</h2>
        <p style={{ color: '#64748B', marginBottom: '24px', fontSize: '14px' }}>กรุณาเข้าสู่ระบบเพื่อยืมอุปกรณ์</p>

        <form onSubmit={handleLogin} style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
          <div>
            <label style={{ display: 'block', fontSize: '13px', fontWeight: '600', color: '#475569', marginBottom: '6px' }}>ชื่อผู้ใช้งาน (Username)</label>
            <input 
              type="text" 
              placeholder="กรอกชื่อผู้ใช้งาน หรือพิมพ์ admin" 
              value={username}
              onChange={(e) => setUsername(e.target.value)}
              required
              style={{
                width: '100%',
                padding: '12px',
                borderRadius: '8px',
                border: '1px solid #CBD5E1',
                outline: 'none',
                fontSize: '14px',
                background: '#F8FAFC'
              }}
            />
          </div>

          <div>
            <label style={{ display: 'block', fontSize: '13px', fontWeight: '600', color: '#475569', marginBottom: '6px' }}>รหัสผ่าน (Password)</label>
            <input 
              type="password" 
              placeholder="••••••••" 
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              required
              style={{
                width: '100%',
                padding: '12px',
                borderRadius: '8px',
                border: '1px solid #CBD5E1',
                outline: 'none',
                fontSize: '14px',
                background: '#F8FAFC'
              }}
            />
          </div>

          <button
            type="submit"
            style={{
              marginTop: '8px',
              padding: '12px',
              background: '#2563EB',
              color: '#FFFFFF',
              border: 'none',
              borderRadius: '8px',
              fontWeight: '600',
              fontSize: '15px',
              cursor: 'pointer',
              transition: 'background 0.2s'
            }}
          >
            เข้าสู่ระบบ
          </button>
        </form>

        <p style={{ textAlign: 'center', marginTop: '24px', fontSize: '14px', color: '#64748B' }}>
          ยังไม่มีบัญชีใช่ไหม? <Link to="/register" style={{ color: '#2563EB', textDecoration: 'none', fontWeight: '600' }}>สมัครสมาชิก</Link>
        </p>
      </div>
    </div>
  );
}
